export async function yieldToMain(): Promise<void> {
  // 1. Native Prioritized Task Scheduling API
  if ('scheduler' in window && 'yield' in (window.scheduler as any)) {
    return await (window.scheduler as any).yield();
  }

  // 2. High-performance micro-task fallback using MessageChannel
  if (typeof MessageChannel !== 'undefined') {
    return new Promise((resolve) => {
      const channel = new MessageChannel();
      channel.port1.onmessage = () => resolve();
      channel.port2.postMessage(null);
    });
  }

  // 3. Last-resort fallback for legacy engines
  return new Promise((resolve) => setTimeout(resolve, 0));
}

import { yieldToMain } from './yieldToMain';

interface ProcessOptions {
  budgetMs?: number;
}

export async function processInBatches<T>(
  items: T[],
  processor: (item: T, index: number) => void,
  options: ProcessOptions = {}
): Promise<void> {
  const budget = options.budgetMs ?? 10; // 10ms frame budget
  let lastYieldTime = performance.now();

  for (let i = 0; i < items.length; i++) {
    processor(items[i], i);

    // Check if the allotted main-thread slice has elapsed
    if (performance.now() - lastYieldTime > budget) {
      await yieldToMain();
      lastYieldTime = performance.now();
    }
  }
}

import React, { useState, useTransition } from 'react';
import { processInBatches } from './timeSlicedProcess';

interface OrderItem {
  id: string;
  tableId: number;
  amount: number;
  taxRate: number;
}

export const OrderMetricsCalculator: React.FC<{ rawOrders: OrderItem[] }> = ({
  rawOrders,
}) => {
  const [isPending, startTransition] = useTransition();
  const [aggregatedTotal, setAggregatedTotal] = useState<number>(0);
  const [status, setStatus] = useState<'idle' | 'computing' | 'done'>('idle');

  const runAudit = () => {
    setStatus('computing');

    startTransition(async () => {
      let runningTotal = 0;

      await processInBatches(
        rawOrders,
        (order) => {
          // Simulating non-trivial business logic & tax rule evaluation
          const tax = order.amount * order.taxRate;
          runningTotal += order.amount + tax;
        },
        { budgetMs: 8 } // Leaves 8ms per frame for DOM paints & tap events
      );

      setAggregatedTotal(runningTotal);
      setStatus('done');
    });
  };

  return (
    <div className="p-6 rounded-xl bg-neutral-900 border border-neutral-800 text-white">
      <div className="flex items-center justify-between gap-4">
        <button
          onClick={runAudit}
          disabled={status === 'computing'}
          className="px-4 py-2 bg-emerald-600 hover:bg-emerald-500 rounded font-medium disabled:opacity-50"
        >
          {status === 'computing' ? 'Auditing Batch...' : 'Run Shift Audit'}
        </button>
        <span className="text-sm text-neutral-400">
          Calculated: ₹{aggregatedTotal.toFixed(2)}
        </span>
      </div>
    </div>
  );
};
